include "Facts.dfy"
module ClientA {
  import F = Facts`ViewA
  lemma SumTwo(s: seq<int>, t: seq<int>)
    ensures F.Total(s + t) == F.Total(s) + F.Total(t)
  { F.AppendA(s, t); }
}

files.ClientB.dfy:
include "Facts.dfy"
module ClientB {
  import F = Facts`ViewA
  lemma SumThree(s: seq<int>, t: seq<int>, u: seq<int>)
    ensures F.Total((s + t) + u) == F.Total(s) + F.Total(t) + F.Total(u)
  {
    F.AppendA(s, t);
    F.AppendA(s + t, u);
  }
}

files.Facts.dfy:
module Facts {
  export ViewA provides Total, AppendA
  function Total(s: seq<int>): int
    decreases |s|
  { if |s| == 0 then 0 else s[0] + Total(s[1..]) }
  lemma {:induction false} AppendA(s: seq<int>, t: seq<int>)
    ensures Total(s + t) == Total(s) + Total(t)
    decreases |s|
  {
  }
}
